import {allActions,reason,effective,removable,additionPool,stateMods,OMEN_RULES,applyCraft,undoCraft,ranges,rolled,recommend,VERSION,intrinsicQualityCap,socketCap} from './craft-engine.mjs';
import {families,tier,allowed,caps} from './engine.mjs';
export function createWorkbench(ctx){
 const {$,esc,modal,toast,current,group,save,replaceProject,store,pricing}=ctx;
 const catalog=window.CRAFTING_DATA;
 const findAction=id=>allActions(group(),catalog).find(a=>a.id===id);
 const field=(label,id,value='',type='text',extra='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${extra}></div>`;
 const note=(t)=>`<p class="section-note">${t}</p>`;
 const money=val=>val===''?null:Number(val);
 const omenMeta=id=>catalog.omens.find(o=>o.id===id)||{id,name:id.replaceAll('_',' '),description:'Эффект по данным каталога.'};
 function overview(){const p=current(),ms=stateMods(p,group());return `<section class="panel advanced-panel"><div class="panel-head"><h2><span>⚒</span> Инструменты крафта <span class="badge">v${VERSION}</span></h2><div class="actions"><button class="text-button" id="item-flags">Состояние вещи</button><button class="button secondary small" id="undo-step" ${p.history?.length?'':'disabled'}>↶ Отменить шаг</button><button class="button small" id="open-tools">Все операции →</button></div></div><div class="advanced-status"><span>Качество <strong>${p.quality||0}%</strong></span><span>Гнёзда <strong>${(p.augments||[]).length}/${p.sockets||0}</strong></span><span>Раскол <strong>${ms.filter(m=>m.fractured).length}</strong></span><span>Crafted <strong>${ms.filter(m=>m.crafted).length}</strong></span><span>Бездна <strong>${ms.filter(m=>m.desecrated||['desecrated','unrevealed'].includes(m.source)).length}</strong></span><span class="${p.corrupted?'danger':''}">${p.destroyed?'Уничтожен':p.mirrored?'Зеркальная копия':p.sanctified?'Освящён':p.corrupted?'Осквернён':'Можно изменять'}</span><span>${p.leagueMode==='standard'?'Standard':p.leagueMode==='legacy'?'Архив механик':'Текущая лига'}</span></div>${p.foresight?`<p class="foresight">◈ Предвидение игрока: ${esc(p.foresight)}</p>`:''}${p.augments?.length?`<div class="augment-list">${p.augments.map(a=>`<span class="badge gray" title="${esc(a.roll)}">${esc(group().special?.socketable?.find(s=>s.id===a.id)?.name||'Augment')}</span>`).join('')}</div>`:''}${p.enchantments?`<p class="foresight">✧ ${esc(p.enchantments)}</p>`:''}</section>`}
 function bind(){const on=(id,fn)=>{if($(id))$(id).onclick=fn};on('#open-tools',openTools);on('#item-flags',stateDialog);on('#undo-step',()=>{modal('Отменить последний шаг?',`<p class="modal-info">Будет восстановлено состояние до операции «${esc(current().history.at(-1).label)}» и удалены расходы именно этого шага. Это меняет только запись в помощнике.</p>`,'<button class="button" id="confirm-undo-step">Восстановить состояние</button>');$('#confirm-undo-step').onclick=()=>{replaceProject(undoCraft(current()));$('#modal').close();toast('Последний шаг отменён')}});document.querySelectorAll('[data-flags]').forEach(el=>el.onclick=()=>modFlags(el.dataset.flags));on('#next-record',()=>{const id=$('#next-record').dataset.action;if(id)setup(findAction(id));else if(ctx.chooseGoals)ctx.chooseGoals()});}
 function nextHTML(){const n=recommend(current(),group(),catalog),last=current().lastOutcome;return `${last?`<div class="last-outcome">✓ Последний шаг: <strong>${esc(last.roll)}</strong></div>`:''}<section class="next-step"><span class="orb"></span><div><div class="eyebrow">СЛЕДУЮЩИЙ ШАГ · С УЧЁТОМ СОСТОЯНИЯ ВЕЩИ</div><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p>${n.action?pricing.priceHTML((findAction(n.action)?.currency||n.action).replaceAll('_',' ')):''}</div><button class="button secondary small" id="next-record" data-action="${esc(n.action||'')}">${n.action?'Выбрать омены и записать исход →':'Изменить цели ↗'}</button></section>${overview()}`}
 function openTools(){const actions=allActions(group(),catalog),categories=[...new Set(actions.map(a=>a.category))];modal('Все операции крафта',`<p class="modal-info">Выберите валюту, затем совместимые предзнаменования. Исход берётся из игры. Наличие записи в каталоге не гарантирует доступность валюты в вашей лиге.</p><div class="two-fields"><input class="search-input" id="action-search" aria-label="Поиск операции" placeholder="Раскол, отмена, Perfect, эссенция…"><select class="search-input" id="action-category" aria-label="Категория операции"><option value="">Все категории</option>${categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><label class="checkline"><input type="checkbox" id="only-available"> Только доступные сейчас</label><div class="picker-list action-list" id="action-results"></div>`);const fill=()=>{const q=$('#action-search').value.toLowerCase(),cat=$('#action-category').value;const list=actions.filter(a=>(!cat||a.category===cat)&&(a.name+' '+a.id+' '+a.description).toLowerCase().includes(q)).map(a=>({a,why:reason(current(),group(),a)})).filter(x=>!$('#only-available').checked||!x.why);$('#action-results').innerHTML=list.map(({a,why},i)=>`<button class="picker-option ${why?'unavailable':''}" data-action-index="${i}">${a.img?`<img src="${esc(a.img)}" alt="" loading="lazy">`:'<span class="orb"></span>'}<span class="affix-copy">${esc(a.name)}<small>${esc(a.id.replaceAll('_',' '))}${a.floor?' · min mod level '+a.floor:''}</small><small class="${why?'danger':''}">${esc(why||a.description||actionDescription(a))}</small>${pricing.priceHTML((a.currency||a.id).replaceAll('_',' '))}</span><span>${why?'ⓘ':'›'}</span></button>`).join('')||'<p class="empty-state">Подходящих операций нет.</p>';document.querySelectorAll('[data-action-index]').forEach(el=>el.onclick=()=>setup(list[+el.dataset.actionIndex].a))};$('#action-search').oninput=fill;$('#action-category').onchange=fill;$('#only-available').onchange=fill;fill()}
 function actionDescription(a){return ({transmute:'Обычный → магический, один случайный мод',augment:'Добавляет случайный мод магическому предмету',regal:'Магический → редкий, один новый мод',exalt:'Добавляет случайный мод редкому предмету',chaos:'Снимает случайный мод и добавляет новый',annul:'Удаляет случайный незакреплённый мод',alchemy:'Обычный → редкий, четыре новых мода',fracture:'Закрепляет случайный подходящий мод',divine:'Меняет значения в пределах существующих тиров; не меняет закреплённые моды',desecrate:'Накладывает скрытый мод Бездны; на полном предмете снимает случайный мод',reveal:'Запишите показанные в Колодце душ варианты, затем выбранный результат',essence:'Магический → редкий с гарантированным crafted-модом','essence-replace':'Случайное удаление и гарантированный crafted-мод',quality:'Укажите реальное новое качество после применения',infuser:'Повышает качество сверх обычного максимума, может осквернить',catalyst:'Меняет тип и величину качества бижутерии',socket:'Добавляет одно гнездо Augment',socketable:'Вставляет или заменяет Augment в гнезде',vaal:'Непредсказуемое осквернение: внесите фактическое полное состояние',architect:'Изменяет осквернённый предмет или уничтожает: внесите фактический исход',sacrifice:'Улучшает corruption enchantment и снимает случайный мод',chance:'Уникальный предмет или уничтожение; омен может изменить исходы',mirror:'Создаёт отдельный проект зеркальной копии; исходный проект сохраняется',recombine:'Историческая операция. Укажите второй предмет и фактическое итоговое состояние',runeforge:'Выберите новую базу, запишите рецепт и материалы, затем итоговое состояние',foresight:'Сохраните реально увиденный в игре исход следующей валюты. Приложение его не предсказывает',flux:'Поднимает уровень встроенного умения до 20','resist-flux':'Переводит сопротивления по таблице эквивалентности игры. Внесите фактический итог; повторяющиеся переведённые сопротивления поддерживаются'})[a.type]||'Внесите наблюдаемый исход'}
 function setup(a){if(!a){toast('Операция не найдена');return}const p=current(),g=group(),om=Object.values(OMEN_RULES).filter(o=>o.types.includes(a.type));modal(a.name,`<p class="modal-info">${esc(a.description||actionDescription(a))}</p><p class="section-note"><a href="${esc(a.source)}" target="_blank" rel="noopener">Описание в PoE2DB ↗</a>${a.floor?` · Минимальный уровень мода: ${a.floor}. Если семейство иначе исключалось бы целиком, остаётся его старший доступный тир.`:''}</p>${a.guaranteed?`<div class="guaranteed-list">${a.guaranteed.map(id=>`<p>✧ ${esc(g.mods.find(m=>m.id===id)?.text)}</p>`).join('')}</div>`:''}${om.length?`<h3 style="margin:18px 0 8px">Совместимые предзнаменования</h3><div class="omen-list">${om.map(o=>{const m=omenMeta(o.id);return `<label class="omen-option"><input type="checkbox" data-omen="${o.id}"><span>${esc(m.name)}<small>${esc(m.description)}</small>${/Homogenising|Omen_of_Corruption$/.test(o.id)?'<small>Standard / архив · Homogenising проверяется по явным тегам модов</small>':''}</span></label>`}).join('')}</div>`:''}<div id="operation-error" class="inline-warning"></div><p class="section-note">Это выбор реального действия, а не случайный бросок внутри приложения. Сфера и сработавшие омены будут записаны только после ввода результата.</p>`,'<button class="button secondary" id="back-tools">← Все операции</button><button class="button" id="start-operation">Применил в игре → внести исход</button>');const check=()=>{const ids=[...document.querySelectorAll('[data-omen]:checked')].map(el=>el.dataset.omen),why=reason(p,g,a,ids);$('#operation-error').textContent=why||'Операция доступна. Учитываются все выбранные эффекты.';$('#operation-error').classList.toggle('ok',!why);$('#start-operation').disabled=!!why;return ids};document.querySelectorAll('[data-omen]').forEach(el=>el.onchange=check);check();$('#back-tools').onclick=openTools;$('#start-operation').onclick=()=>start({a,omenIds:check(),result:{removed:[],added:[]}})}
 function start(d){const p=current(),g=group(),x=effective(p,g,d.a,d.omenIds);d.x=x;const type=d.a.type;if(x.removeCount||type==='desecrate'&&!x.putrefaction&&(p.mods.length>=6||stateMods(p,g).some(m=>m.currency==='Essence_of_the_Abyss'))){d.needRemove=x.removeCount||1;return removeDialog(d)}return nextPhase(d)}
 function removeDialog(d){const mark=stateMods(current(),group()).find(m=>m.currency==='Essence_of_the_Abyss');const options=removable(current(),group(),d.x).filter(m=>d.a.type!=='desecrate'||!mark||m.id===mark.id);modal('Какой мод исчез в игре?',`<p class="modal-info">Укажите ${d.needRemove} реально снятых аффикса. Вы не выбираете цель для удаления перед броском: снятие уже произошло в игре.</p><div class="picker-list">${options.map(m=>`<label class="omen-option"><input type="checkbox" data-removed="${esc(m.id)}"><span>${esc(m.roll||m.text)}<small>${m.kind===1?'Префикс':'Суффикс'} · уровень мода ${m.level}${m.crafted?' · crafted':''}${m.desecrated?' · Бездна':''}</small></span></label>`).join('')}</div><p id="removed-error" class="error"></p>`,'<button class="button" id="removed-next">Далее →</button>');$('#removed-next').onclick=()=>{const ids=[...document.querySelectorAll('[data-removed]:checked')].map(el=>el.dataset.removed);if(ids.length!==d.needRemove){$('#removed-error').textContent=`Выберите ровно ${d.needRemove} аффикса`;return}d.result.removed=ids;nextPhase(d)}}
 function nextPhase(d){const t=d.a.type;if(['transmute','augment','regal','exalt','chaos','essence','essence-replace','alchemy'].includes(t))return addDialog(d);if(t==='reveal')return revealDialog(d);if(t==='desecrate')return boneDialog(d);if(t==='fracture')return fractureDialog(d);if(t==='divine')return divineDialog(d);if(['vaal','architect','recombine','runeforge','resist-flux'].includes(t))return observedDialog(d);return resultDialog(d)}
 function addDialog(d){const p=current(),g=group(),options=additionPool(p,g,d.x,d.result.removed,d.result.added);const fs=families({mods:options});modal(`Что добавилось? ${d.result.added.length+1} / ${d.x.addCount}`,`<p class="modal-info">${d.a.guaranteed?'Выберите гарантированный вариант для вашей базы и укажите его реальное значение.':'Выберите выпавшее семейство, затем тир и точное значение.'}</p><input class="search-input" id="added-search" aria-label="Поиск нового аффикса" placeholder="Урон, жизнь, скорость…"><div class="picker-list" id="added-results"></div>`);const fill=()=>{const q=$('#added-search').value.toLowerCase(),list=fs.filter(f=>(f.tiers[0].text+' '+f.key).toLowerCase().includes(q));$('#added-results').innerHTML=list.map((f,i)=>`<button class="picker-option" data-added-family="${i}"><span class="badge ${f.kind===2?'purple':'gold'}">${f.kind===1?'П':'С'}</span><span class="affix-copy">${esc(f.tiers[0].text)}<small>${f.tiers.length} доступных тиров · ${esc(f.tiers[0].source||'обычный')}</small></span><span>›</span></button>`).join('')||'<p class="empty-state">Нет совместимых вариантов. Проверьте фактически снятый мод, ограничения оменов и оставшиеся слоты.</p>';document.querySelectorAll('[data-added-family]').forEach(el=>el.onclick=()=>rollDialog(list[+el.dataset.addedFamily].tiers,z=>{d.result.added.push(z);if(d.result.added.length<d.x.addCount)addDialog(d);else confirmDialog(d)},()=>addDialog(d)))};$('#added-search').oninput=fill;fill()}
 function rollDialog(options,onDone,onBack){modal('Тир и фактическое значение',`<div class="field"><label for="new-mod-tier">Тир · диапазон</label><select id="new-mod-tier">${options.map(m=>`<option value="${m.id}">${m.source?esc(m.source)+' · ':''}T${tier(group(),m)} · ilvl ${m.level} · ${esc(m.text)}</option>`).join('')}</select></div><div id="new-values"></div><div class="roll-preview" id="new-preview"></div><p id="new-value-error" class="error"></p>`,'<button class="button secondary" id="new-back">← Назад</button><button class="button" id="new-mod-save">Записать значение →</button>');const selected=()=>options.find(m=>m.id===$('#new-mod-tier').value);const fill=()=>{const rs=ranges(selected());$('#new-values').innerHTML=rs.length?`<div class="two-fields">${rs.map((r,i)=>field(`Значение ${i+1} · ${r.min}–${r.max}`,'roll-'+i,'','number',`step="any" min="${r.min}" max="${r.max}" data-new-roll="${i}"`)).join('')}</div>`:note('У этого тира фиксированное значение.');$('#new-preview').textContent=selected().text;document.querySelectorAll('[data-new-roll]').forEach(el=>el.oninput=()=>{let i=0;$('#new-preview').textContent=selected().text.replace(/\((-?\d+(?:\.\d+)?)—(-?\d+(?:\.\d+)?)\)/g,()=>$('#roll-'+i++).value||'?')})};$('#new-mod-tier').onchange=fill;fill();$('#new-back').onclick=onBack;$('#new-mod-save').onclick=()=>{try{const m=selected(),els=[...document.querySelectorAll('[data-new-roll]')];if(els.some(el=>el.value===''))throw Error('Заполните все значения');const values=els.map(el=>+el.value);rolled(m,values);onDone({id:m.id,values})}catch(e){$('#new-value-error').textContent=e.message}}}
 function fractureDialog(d){const list=stateMods(current(),group()).filter(m=>!m.fractured&&!m.desecrated&&!['unrevealed','desecrated'].includes(m.source));modal('Какой мод закрепился?',`<p class="modal-info">Выберите результат случайного раскола в игре. Раскол не снимает признак crafted.</p><div class="picker-list">${list.map((m,i)=>`<button class="picker-option" data-fractured="${i}">${esc(m.roll||m.text)}</button>`).join('')}</div>`);document.querySelectorAll('[data-fractured]').forEach(el=>el.onclick=()=>{d.result.fracturedId=list[+el.dataset.fractured].id;confirmDialog(d)})}
 function boneDialog(d){const p=current(),x=d.x;modal('Нераскрытое свойство Бездны',`<p class="modal-info">${x.putrefaction?'Укажите число скрытых префиксов и суффиксов после Putrefaction. Предмет станет осквернённым.':'Укажите, какой слот заняло скрытое свойство. Его раскроете отдельным шагом у Колодца душ.'}</p>${x.putrefaction?`<div class="two-fields">${field('Скрытые префиксы','bone-prefix',0,'number','min="0" max="3"')}${field('Скрытые суффиксы','bone-suffix',0,'number','min="0" max="3"')}</div>`:`<div class="field"><label for="bone-kind">Занятый слот</label><select id="bone-kind">${[1,2].filter(k=>!x.addKind||x.addKind===k).map(k=>`<option value="${k}">${k===1?'Префикс':'Суффикс'}</option>`).join('')}</select></div>`}<p id="bone-error" class="error"></p>`,'<button class="button" id="bone-next">Записать скрытые моды →</button>');$('#bone-next').onclick=()=>{let ks;if(x.putrefaction){const a=+$('#bone-prefix').value,b=+$('#bone-suffix').value;if(!Number.isInteger(a)||!Number.isInteger(b)||a<0||b<0||a>3||b>3||a+b===0){$('#bone-error').textContent='Допустимо до трёх префиксов и трёх суффиксов, минимум один мод';return}ks=[...Array(a).fill(1),...Array(b).fill(2)]}else ks=[+$('#bone-kind').value];d.result.unrevealedKinds=ks;confirmDialog(d)}}
 function revealDialog(d){const p=current(),g=group(),pending=stateMods(p,g).filter(m=>m.source==='unrevealed');modal('Раскрытие у Колодца душ',`<p class="modal-info">Внесите реально предложенные игрой варианты, затем выберите один. ${d.x.echoes?'Предзнаменование эха позволяет один раз обновить варианты в игре. Внесите итоговый список после обновления.':''}</p><div class="field"><label for="reveal-pending">Раскрываемый мод</label><select id="reveal-pending">${pending.map(m=>`<option value="${m.id}">${m.kind===1?'Скрытый префикс':'Скрытый суффикс'} · ${esc(m.id.split('-').at(-1))}</option>`).join('')}</select></div><div id="reveal-pool"></div>`);$('#reveal-pending').onchange=()=>fill();const fill=()=>{const m=pending.find(m=>m.id===$('#reveal-pending').value),before=structuredClone(p);before.mods=before.mods.filter(z=>z.id!==m.id);const x={...d.x,addKind:m.kind,floor:m.pendingFloor||0,abyssTag:m.abyssTag||'',otherworldly:!!m.otherworldly,revealId:m.id};const options=additionPool(before,g,x,[],[]);$('#reveal-pool').innerHTML=`<p class="section-note">Обычный мод, полученный через Бездну, тоже сохранит признак desecrated.</p>${[0,1,2].map(i=>`<div class="field"><label for="offered-${i}">Предложенный вариант ${i+1}${i?' (необязательно)':''}</label><select id="offered-${i}"><option value="">Выберите из увиденного в игре</option>${options.map(o=>`<option value="${o.id}">${o.source==='desecrated'?'✧ Бездна · ':''}${esc(o.text)} · ilvl ${o.level}</option>`).join('')}</select></div>`).join('')}<button class="button wide" id="choose-reveal">Выбрать один из вариантов →</button><p id="reveal-error" class="error"></p>`;$('#choose-reveal').onclick=()=>{const ids=[0,1,2].map(i=>$('#offered-'+i).value).filter(Boolean);if(!ids.length){$('#reveal-error').textContent='Укажите хотя бы один реально предложенный вариант';return}d.result.revealId=m.id;d.result.offered=ids;modal('Какой вариант вы выбрали?',`<div class="picker-list">${ids.map((id,i)=>`<button class="picker-option" data-reveal-choice="${i}">${esc(g.mods.find(m=>m.id===id).text)}</button>`).join('')}</div>`);document.querySelectorAll('[data-reveal-choice]').forEach(el=>el.onclick=()=>rollDialog([g.mods.find(m=>m.id===ids[+el.dataset.revealChoice])],z=>{d.result.added=[z];confirmDialog(d)},()=>revealDialog(d)))}};fill()}
 function divineDialog(d){if(d.x.implicitOnly){modal('Новые собственные свойства',`<div class="field"><label for="implicit-result">Скопируйте реальные implicit-значения после Divine</label><textarea id="implicit-result" maxlength="1500">${esc(current().implicitRoll||'')}</textarea></div>`,'<button class="button" id="implicit-save">Далее →</button>');$('#implicit-save').onclick=()=>{d.result.implicitRoll=$('#implicit-result').value;confirmDialog(d)};return}const list=stateMods(current(),group()).filter(m=>!m.fractured&&m.source!=='unrevealed');d.result.rerolls=[];function next(i){if(i>=list.length)return confirmDialog(d);const m=list[i];if(d.x.sanctify){modal(`Освящённое значение ${i+1}/${list.length}`,`<p class="modal-info">${esc(m.roll||m.text)}</p>${field('Фактический стат после освящения','sanctified-roll',m.roll||m.text,'text','maxlength="500"')}<p class="section-note">Множитель освящения может вывести значение за обычный диапазон тира.</p>`,'<button class="button" id="sanctified-next">Далее →</button>');$('#sanctified-next').onclick=()=>{d.result.rerolls.push({id:m.id,roll:$('#sanctified-roll').value});next(i+1)}}else rollDialog([m],z=>{d.result.rerolls.push(z);next(i+1)},()=>setup(d.a))}next(0)}
 function resultDialog(d){const p=current(),g=group(),t=d.a.type;let body='';if(['quality','infuser','catalyst'].includes(t))body=`${field('Итоговое качество в игре, %','result-quality',p.quality||0,'number',`min="0" max="${intrinsicQualityCap(p,g)+(t==='infuser'?10:0)}"`)}${t==='infuser'?'<label class="checkline"><input type="checkbox" id="result-corrupted"> Предмет осквернился</label>':''}`;
 if(t==='chance')body=`<div class="field"><label for="chance-result">Реальный исход</label><select id="chance-result"><option value="unique">Получился уникальный предмет</option>${!d.x.noDestroy?'<option value="destroyed">Предмет уничтожен</option>':'<option value="unchanged">Предмет сохранился без изменения</option>'}</select></div>${field('Название уникального предмета','unique-name','','text','maxlength="150"')}`;
 if(t==='socketable')body=`<p class="modal-info">${esc(d.a.description)}</p><div class="field"><label for="socket-index">Гнездо</label><select id="socket-index">${Array.from({length:p.sockets||0},(_,i)=>`<option value="${i}">Гнездо ${i+1}: ${esc(g.special.socketable.find(a=>a.id===p.augments?.[i]?.id)?.name||'пусто')}</option>`).join('')}</select></div>${note('При замене старый Augment будет уничтожен. Сам предмет и его аффиксы сохраняются.')}`;
 if(t==='foresight')body=`${field('Наблюдаемый исход следующей валюты','lock-preview',p.foresight||'','text','maxlength="1500"')}${note('Берите исход из игрового предвидения. Любое последующее изменение вещи снимает эту запись.')}`;
 if(t==='sacrifice')body=`<div class="field"><label for="sacrifice-enchant">Улучшенное corruption enchantment</label><textarea id="sacrifice-enchant" maxlength="1500">${esc(p.enchantments||'')}</textarea></div>`;
 if(t==='mirror')body='<p class="modal-info">Будет создан отдельный проект зеркальной копии с текущими аффиксами и вложениями. Исходная вещь сохранится. После копирования её нельзя изменять обычными операциями.</p>';
 if(t==='socket'||t==='flux')body=`<p class="modal-info">${esc(t==='socket'?`Гнёзд после применения: ${(p.sockets||0)+1}`:'Уровень встроенного умения после применения: 20')}</p>`;
 modal(d.a.name,body||`<p class="modal-info">${esc(actionDescription(d.a))}</p>`,'<button class="button" id="simple-next">Проверить и записать →</button>');$('#simple-next').onclick=()=>{if(['quality','infuser','catalyst'].includes(t)){d.result.quality=+$('#result-quality').value;d.result.corrupted=!!$('#result-corrupted')?.checked}if(t==='chance'){d.result.outcome=$('#chance-result').value;d.result.uniqueName=$('#unique-name').value}if(t==='socketable')d.result.socketIndex=+$('#socket-index').value;if(t==='foresight')d.result.description=$('#lock-preview').value;if(t==='sacrifice')d.result.enchantments=$('#sacrifice-enchant').value;confirmDialog(d)}}
 function observedDialog(d){const p=current(),g=group();let draftMods=structuredClone(p.mods);function screen(){modal('Запишите итоговое состояние',`<p class="modal-info">Для ${esc(d.a.name)} результат не генерируется. Перенесите изменения из игры: база, аффиксы, качество, гнёзда и enchantment. Затем помощник продолжит с этого состояния.</p>${d.a.type==='architect'?'<label class="checkline"><input type="checkbox" id="architect-destroyed"> Предмет уничтожен</label>':''}<div class="field"><label for="observed-base">База после операции</label><select id="observed-base">${g.bases.map(b=>`<option value="${b.id}" ${b.id===p.base?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div class="two-fields"><div class="field"><label for="observed-rarity">Редкость</label><select id="observed-rarity">${['normal','magic','rare'].map(r=>`<option ${r===p.rarity?'selected':''}>${r}</option>`).join('')}</select></div>${field('Качество','observed-quality',p.quality||0,'number','min="0" max="100"')}</div>${field('Гнёзда','observed-sockets',p.sockets||0,'number','min="0" max="6"')}<div class="observed-mods">${draftMods.map((m,i)=>`<div class="target-row"><span class="affix-copy">${esc(m.roll||g.mods.find(x=>x.id===m.id)?.text)}</span><button class="tiny-button" data-observed-remove="${i}" aria-label="Убрать мод из результата">×</button></div>`).join('')}</div><button class="empty-slot" id="observed-add">＋ Добавить фактический мод</button><div class="field"><label for="observed-enchant">Corruption enchantment / особые свойства</label><textarea id="observed-enchant" maxlength="1500">${esc(p.enchantments||'')}</textarea></div>${field('Рецепт, материалы / второй предмет','observed-description',d.result.description||'','text','maxlength="500"')}<p id="observed-error" class="error"></p>`,'<button class="button" id="observed-next">Проверить итог →</button>');document.querySelectorAll('[data-observed-remove]').forEach(el=>el.onclick=()=>{draftMods.splice(+el.dataset.observedRemove,1);screen()});$('#observed-add').onclick=()=>{const picked=draftMods.map(z=>g.mods.find(m=>m.id===z.id)),options=g.mods.filter(m=>m.source!=='unrevealed'&&(d.a.type!=='resist-flux'||m.source==='converted'&&m.families.includes(d.a.targetFamily))&&allowed({...m,converted:d.a.type==='resist-flux'&&m.families.includes(d.a.targetFamily)},picked,'rare',p.level));modal('Добавить мод из результата',`<input class="search-input" id="observed-search" aria-label="Поиск итогового мода" placeholder="Начните вводить стат…"><div class="picker-list" id="observed-pool"></div>`);const fill=()=>{const q=$('#observed-search').value.toLowerCase(),list=options.filter(m=>(m.text+' '+m.name).toLowerCase().includes(q));$('#observed-pool').innerHTML=list.map((m,i)=>`<button class="picker-option" data-observed-pick="${i}">${esc(m.text)} · ${esc(m.source||'обычный')} · ilvl ${m.level}</button>`).join('');document.querySelectorAll('[data-observed-pick]').forEach(el=>el.onclick=()=>rollDialog([list[+el.dataset.observedPick]],z=>{const m=g.mods.find(m=>m.id===z.id);draftMods.push({...z,roll:rolled(m,z.values),crafted:!!m.crafted,desecrated:m.source==='desecrated',converted:d.a.type==='resist-flux'&&m.families.includes(d.a.targetFamily)});screen()},screen))};$('#observed-search').oninput=fill;fill()};$('#observed-next').onclick=()=>{if($('#architect-destroyed')?.checked){d.result.outcome='destroyed';return confirmDialog(d)}d.result.observed={base:$('#observed-base').value,rarity:$('#observed-rarity').value,quality:+$('#observed-quality').value,sockets:+$('#observed-sockets').value,mods:draftMods,enchantments:$('#observed-enchant').value};d.result.description=$('#observed-description').value;confirmDialog(d)}}screen()}
 function confirmDialog(d){const p=current(),t=d.a.type,currency=(d.a.currency||d.a.id).replaceAll('_',' '),stepQuote=pricing.quote(currency),omenQuotes=Object.fromEntries(d.omenIds.map(id=>[id,pricing.quote(id.replaceAll('_',' '))]));modal('Подтвердите записанный исход',`<div class="outcome-summary"><span class="orb"></span><div><strong>${esc(d.a.name)}</strong><p>${esc(d.result.added?.map(z=>rolled(group().mods.find(m=>m.id===z.id),z.values)).join(' · ')||actionDescription(d.a))}</p></div></div>${d.result.removed?.length?`<p class="section-note">Снято: ${d.result.removed.map(id=>esc(stateMods(p,group()).find(m=>m.id===id)?.roll||group().mods.find(m=>m.id===id)?.text)).join(' · ')}</p>`:''}${field('Стоимость использованной валюты, ex','craft-rate',stepQuote.value??'','number','min="0" step="any"')}${d.omenIds.map((id,i)=>field('Цена: '+esc(omenMeta(id).name)+', ex','omen-rate-'+i,omenQuotes[id].value??'','number','min="0" step="any"')).join('')}<p class="section-note">${esc(pricing.hint(currency))}. Курс сохранится в этом расходе.</p>${field('Комментарий','craft-note',d.result.description||d.a.name,'text','maxlength="500"')}${note('Одна единица выбранной валюты и каждого сработавшего омена. Для нескольких применений записывайте каждый исход отдельно. Неизвестный курс оставьте пустым.')}<p id="commit-error" class="error"></p>`,'<button class="button secondary" id="commit-cancel">Отмена</button><button class="button" id="commit-craft">Сохранить и следующий шаг →</button>');$('#commit-cancel').onclick=()=>$('#modal').close();$('#commit-craft').onclick=()=>{try{d.result.rate=money($('#craft-rate').value);d.result.omenRates=Object.fromEntries(d.omenIds.map((id,i)=>[id,money($('#omen-rate-'+i).value)]));d.result.description=$('#craft-note').value;d.result.quoteInfo=pricing.provenance(currency,d.result.rate,stepQuote);d.result.omenQuoteInfo=Object.fromEntries(d.omenIds.map(id=>[id,pricing.provenance(id.replaceAll('_',' '),d.result.omenRates[id],omenQuotes[id])]));const next=applyCraft(p,group(),d.a,d.result,d.omenIds);if(d.result.rate!==null)store.rates[(d.a.currency||d.a.id).replaceAll('_',' ')]=d.result.rate;for(const id of d.omenIds)if(d.result.omenRates[id]!==null)store.rates[id.replaceAll('_',' ')]=d.result.omenRates[id];replaceProject(next,{copy:t==='mirror'});$('#modal').close();toast('Шаг записан. Рекомендация обновлена.');$('#next-record')?.scrollIntoView({behavior:'smooth',block:'center'})}catch(e){$('#commit-error').textContent=e.message}}}
 function modFlags(id){const p=current(),m=p.mods.find(m=>m.id===id);modal('Признаки существующего аффикса',`<p class="modal-info">${esc(m.roll||group().mods.find(x=>x.id===id).text)}</p>${['fractured','crafted','desecrated'].map(k=>`<label class="checkline"><input type="checkbox" id="flag-${k}" ${m[k]?'checked':''}> ${{fractured:'Закреплён расколом',crafted:'Crafted — создан эссенцией / сплавом',desecrated:'Получен через Бездну'}[k]}</label>`).join('')}${note('Это исправление описания уже существующего предмета. Оно не применяет валюту и не расходует сферы.')}<p id="flag-error" class="error"></p>`,'<button class="button" id="save-mod-flags">Сохранить признаки</button>');$('#save-mod-flags').onclick=()=>{const flags=Object.fromEntries(['fractured','crafted','desecrated'].map(k=>[k,$('#flag-'+k).checked]));if(flags.fractured&&flags.desecrated){$('#flag-error').textContent='Свойство Бездны не может быть целью раскола';return}if(flags.fractured&&p.mods.some(x=>x.id!==id&&x.fractured)){ $('#flag-error').textContent='На предмете уже есть закреплённый мод';return}if(flags.crafted&&!m.crafted&&p.mods.filter(x=>x.crafted).length>=1+(p.augments||[]).filter(a=>group().special.socketable.find(x=>x.id===a.id)?.currency==='Astrids_Creativity').length){$('#flag-error').textContent='Превышен лимит crafted-модов';return}Object.assign(m,flags);save();$('#modal').close()}}
 function stateDialog(){const p=current(),g=group();modal('Состояние существующего предмета',`<div class="two-fields">${field('Качество, %','state-quality',p.quality||0,'number','min="0" max="100"')}${field('Гнёзда Augment','state-sockets',p.sockets||0,'number','min="0" max="6"')}</div>${field('Особый максимум гнёзд (если есть)','state-socket-cap',p.socketCapOverride||socketCap(p,g),'number','min="0" max="6"')}<div class="field"><label for="state-league">Режим доступности</label><select id="state-league"><option value="current" ${!p.leagueMode||p.leagueMode==='current'?'selected':''}>Текущая лига (исключает legacy)</option><option value="standard" ${p.leagueMode==='standard'?'selected':''}>Standard</option><option value="legacy" ${p.leagueMode==='legacy'?'selected':''}>Архив — исторические механики</option></select></div>${['corrupted','mirrored','sanctified','destroyed'].map(k=>`<label class="checkline"><input id="state-${k}" type="checkbox" ${p[k]?'checked':''}> ${{corrupted:'Осквернён',mirrored:'Зеркальная копия',sanctified:'Освящён',destroyed:'Уничтожен'}[k]}</label>`).join('')}<div class="field" style="margin-top:15px"><label for="state-enchant">Собственные особые / corruption enchantment</label><textarea id="state-enchant" maxlength="1500">${esc(p.enchantments||'')}</textarea></div>${note('Для внесения уже имеющейся вещи. Признаки каждого аффикса задаются кнопкой ◈ возле него. Обычный максимум качества этой базы: '+intrinsicQualityCap(p,g)+'%.')}<p id="state-error" class="error"></p>`,'<button class="button" id="save-item-state">Сохранить состояние</button>');$('#save-item-state').onclick=()=>{const quality=+$('#state-quality').value,sockets=+$('#state-sockets').value,cap=+$('#state-socket-cap').value;if(!Number.isInteger(quality)||quality<0||quality>100||!Number.isInteger(sockets)||sockets<0||sockets>6||!Number.isInteger(cap)||cap<0||cap>6||sockets<(p.augments||[]).length){$('#state-error').textContent='Проверьте качество и число гнёзд. Установленные Augment должны помещаться.';return}Object.assign(p,{quality,sockets,socketCapOverride:cap,leagueMode:$('#state-league').value,enchantments:$('#state-enchant').value});for(const k of ['corrupted','mirrored','sanctified','destroyed'])p[k]=$('#state-'+k).checked;save();$('#modal').close()}}
 return {nextHTML,bind,openTools,setup,recommend:()=>recommend(current(),group(),catalog)};
}
